                "content": "import SidebarMenu from \"../../components/ui/sidebar/menu.marko\";\nimport SidebarMenuItem from \"../../components/ui/sidebar/menu-item.marko\";\nimport SidebarMenuButton from \"../../components/ui/sidebar/menu-button.marko\";\nimport DropdownMenu from \"../../components/ui/dropdown-menu/dropdown-menu.marko\";\nimport type { DropdownMenuItem } from \"../../components/ui/dropdown-menu/dropdown-menu.marko\";\n\nexport interface Input {\n  versions: string[];\n  defaultVersion: string;\n}\n\n<let/selectedVersion=input.defaultVersion/>\n\n<const/menuItems=() => input.versions.map((version) => ({\n  value: version,\n  label: `v${version}${version === selectedVersion ? \" (current)\" : \"\"}`,\n} satisfies DropdownMenuItem))/>\n\n<SidebarMenu>\n  <SidebarMenuItem>\n    <DropdownMenu\n      items=menuItems()\n      select(value) {\n        selectedVersion = value;\n      }\n    >\n      <@trigger|attrs|>\n        <SidebarMenuButton\n          ...attrs\n          size=\"lg\"\n          class=\"data-[state=open]:bg-sidebar-accent data-[state=open]:text-sidebar-accent-foreground\"\n        >\n          <div\n            class=\"flex aspect-square size-8 items-center justify-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground\"\n          >\n            <svg\n              xmlns=\"http://www.w3.org/2000/svg\"\n              width=\"24\"\n              height=\"24\"\n              viewBox=\"0 0 24 24\"\n              fill=\"none\"\n              stroke=\"currentColor\"\n              stroke-width=\"2\"\n              stroke-linecap=\"round\"\n              stroke-linejoin=\"round\"\n              class=\"size-4\"\n            >\n              <path d=\"M6 3h12l4 6-10 13L2 9Z\"/>\n              <path d=\"M11 3 8 9l4 13 4-13-3-6\"/>\n              <path d=\"M2 9h20\"/>\n            </svg>\n          </div>\n          <div class=\"flex flex-col gap-0.5 leading-none\">\n            <span class=\"font-medium\">Documentation</span>\n            <span>v${selectedVersion}</span>\n          </div>\n          <svg\n            xmlns=\"http://www.w3.org/2000/svg\"\n            width=\"24\"\n            height=\"24\"\n            viewBox=\"0 0 24 24\"\n            fill=\"none\"\n            stroke=\"currentColor\"\n            stroke-width=\"2\"\n            stroke-linecap=\"round\"\n            stroke-linejoin=\"round\"\n            class=\"ml-auto size-4\"\n          >\n            <path d=\"m7 15 5 5 5-5\"/>\n            <path d=\"m7 9 5-5 5 5\"/>\n          </svg>\n        </SidebarMenuButton>\n      </@trigger>\n    </DropdownMenu>\n  </SidebarMenuItem>\n</SidebarMenu>\n"
