                "content": "import SidebarProvider from \"../../components/ui/sidebar/provider.marko\";\nimport SidebarTrigger from \"../../components/ui/sidebar/trigger.marko\";\nimport Separator from \"../../components/ui/separator/separator.marko\";\nimport Breadcrumb from \"../../components/ui/breadcrumb/breadcrumb.marko\";\nimport BreadcrumbItem from \"../../components/ui/breadcrumb/item.marko\";\nimport BreadcrumbLink from \"../../components/ui/breadcrumb/link.marko\";\nimport BreadcrumbPage from \"../../components/ui/breadcrumb/page.marko\";\nimport BreadcrumbSeparator from \"../../components/ui/breadcrumb/separator.marko\";\nimport AppSidebar from \"./app-sidebar.marko\";\n\n<SidebarProvider width=\"16rem\">\n  <@sidebar|{ open }|>\n    <AppSidebar open=open/>\n  </@sidebar>\n  <@main|{ open, toggle }|>\n    <div class=\"flex min-w-0 flex-1 flex-col\">\n      <header class=\"flex h-16 shrink-0 items-center gap-2 border-b px-4\">\n        <SidebarTrigger open=open toggle=toggle class=\"-ml-1\"/>\n        <Separator orientation=\"vertical\" class=\"mr-2 h-4\"/>\n        <Breadcrumb>\n          <BreadcrumbItem class=\"hidden md:block\">\n            <BreadcrumbLink href=\"#\">Build Your Application</BreadcrumbLink>\n          </BreadcrumbItem>\n          <BreadcrumbSeparator class=\"hidden md:block\"/>\n          <BreadcrumbItem>\n            <BreadcrumbPage>Data Fetching</BreadcrumbPage>\n          </BreadcrumbItem>\n        </Breadcrumb>\n      </header>\n      <div class=\"flex flex-1 flex-col gap-4 p-4\">\n        <div class=\"grid auto-rows-min gap-4 md:grid-cols-3\">\n          <div class=\"aspect-video rounded-xl bg-muted/50\"></div>\n          <div class=\"aspect-video rounded-xl bg-muted/50\"></div>\n          <div class=\"aspect-video rounded-xl bg-muted/50\"></div>\n        </div>\n        <div class=\"min-h-[100vh] flex-1 rounded-xl bg-muted/50 md:min-h-min\"></div>\n      </div>\n    </div>\n  </@main>\n</SidebarProvider>\n"
